declare
  missing text;
begin
  select string_agg(s, ', ') into missing
  from unnest(array['glossary-strength', 'glossary-sleep', 'news-oral-glp1-2026-05', 'news-loneliness-memory-2026-04', 'summary-outlive', 'summary-why-we-sleep', 'summary-deep-work', 'attachment-styles-love', 'does-money-buy-happiness', 'non-instrumental-play', 'summary-atomic-habits', 'explainer-career-capital', 'glossary-build', 'glossary-career', 'glossary-circle', 'glossary-contemplate', 'glossary-dexterity', 'glossary-learn', 'glossary-money', 'glossary-nutrition', 'glossary-romance', 'summary-good-life', 'summary-psychology-of-money', 'weak-ties-job-search', 'ten-second-balance-test', 'grip-strength-longevity', 'play-deprivation-adults', 'attention-residue', 'ikea-effect', 'cbt-i-vs-sleep-hygiene', 'protein-distribution-30g-myth']) as s
  where not exists (select 1 from public.learning_material m where m.slug = s);
